-- Scale note on the pilot rows already in the tracker
update fs_grant_deadlines set notes = notes || ' SCALE: need is 50 servings a week (20 Tue + 30 Wed), so ask for a 50-serving weekly pilot.'
where funder in ('Jeni''s Splendid Ice Creams','Urban Luxe Cafe (South Shore)','Andy''s Frozen Custard') and notes not like '%SCALE:%';

select count(*) as after_total from fs_grant_deadlines;
